return {
  feint: {
    hook: "onEvent",
    eventType: "swordFeint",
    async promptOnPlayer(H, actor) {
      const target = await H.ask.hunterInZone(H.zone.of(actor), "Noble: choose a Hunter to guard");
      if (!target) return false;
      await H.actions.grantManoeuvre(target, "guard");
      return true;
    },
  },
};
